"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([["79769"],{68489(e){e.exports=JSON.parse('{"tag":{"label":"Behavior","permalink":"/docs/tags/behavior","allTagsPath":"/docs/tags","count":27,"items":[{"id":"Rats/getting-started/rat-care-guide","title":"A Comprehensive Guide to Rat Care","description":"Rats are intelligent, social, and engaging pets that bring a unique joy to any home. To ensure they live long, happy, and healthy lives, it\u2019s essential to understand and meet their specific needs. This guide provides a comprehensive overview of daily and weekly care routines for your pet rats.","permalink":"/docs/Rats/getting-started/rat-care-guide"},{"id":"Rats/breeds-and-genetics/rat-variety-guide","title":"A Guide to Fancy Rat Varieties","description":"Welcome to the colorful world of fancy rats! Through selective breeding, pet rats have been developed in a stunning array of colors, coat types, and markings. While these varieties are fascinating,...","permalink":"/docs/Rats/breeds-and-genetics/rat-variety-guide"},{"id":"Rats/care-and-husbandry/introductions","title":"A Guide to Safe and Successful Rat Introductions","description":"Introducing a new rat to your existing group (or \'mischief\') is an exciting step, but it must be handled with care and patience. Rats are territorial and have complex social hierarchies. A proper...","permalink":"/docs/Rats/care-and-husbandry/introductions"},{"id":"Rabbits/care-and-husbandry/essential-supplies","title":"Essential Supplies for Your Rabbit Companion","description":"Bringing a rabbit into your home is a long-term commitment, and providing the right supplies is the first step to ensuring a happy, healthy life for your new friend. Rabbits have specific needs that...","permalink":"/docs/Rabbits/care-and-husbandry/essential-supplies"},{"id":"general-care/daily-care/is-my-pet-nocturnal","title":"Is My Pet Nocturnal? Understanding Your Pet\'s Active Hours","description":"Learn the difference between nocturnal, diurnal, and crepuscular activity patterns and find out when your small pet is naturally most active. Understanding their sleep cycle is key to providing the best care.","permalink":"/docs/general-care/daily-care/is-my-pet-nocturnal"},{"id":"general-care/daily-care/playing-and-training","title":"Playing & Training Your Small Pet","description":"All small pets benefit from play, enrichment, and mental stimulation. Learn how to engage your pet\'s natural instincts through species-appropriate play, foraging, and positive-reinforcement training.","permalink":"/docs/general-care/daily-care/playing-and-training"},{"id":"Chinchillas/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Chinchilla","description":"Chinchillas are active, athletic animals that need daily out-of-cage time and enrichment. Learn how to safely play with and train your chinchilla.","permalink":"/docs/Chinchillas/care-and-husbandry/playing-and-training"},{"id":"Degus/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Degus","description":"Degus are highly social, intelligent animals that need daily enrichment and interaction. Learn how to play with and train your degus using positive reinforcement.","permalink":"/docs/Degus/care-and-husbandry/playing-and-training"},{"id":"Ferrets/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Ferret","description":"Ferrets are highly playful, mischievous animals that need several hours of out-of-cage time and enrichment daily. Learn how to play with and train your ferret.","permalink":"/docs/Ferrets/care-and-husbandry/playing-and-training"},{"id":"Gerbils/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Gerbil","description":"Gerbils are active, social, and surprisingly trainable. Learn how to enrich your gerbils\' environment and teach them simple behaviors using positive reinforcement.","permalink":"/docs/Gerbils/care-and-husbandry/playing-and-training"},{"id":"guinea-pigs/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Guinea Pig","description":"Guinea pigs are social, curious animals that thrive with daily enrichment and gentle training. Learn how to engage your guinea pig\'s natural instincts through play and positive reinforcement.","permalink":"/docs/guinea-pigs/care-and-husbandry/playing-and-training"},{"id":"Hamsters/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Hamster","description":"Hamsters are intelligent, curious animals that need daily enrichment to stay healthy and happy. Learn how to engage your hamster\'s natural instincts and teach simple behaviors.","permalink":"/docs/Hamsters/care-and-husbandry/playing-and-training"},{"id":"Hedgehogs/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Hedgehog","description":"Hedgehogs are solitary, nocturnal explorers that need nightly enrichment and exercise. Learn how to engage your hedgehog\'s natural instincts and build a bond through gentle handling and simple training.","permalink":"/docs/Hedgehogs/care-and-husbandry/playing-and-training"},{"id":"Mice/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Mice","description":"Mice are highly intelligent, social animals that thrive with daily enrichment and positive-reinforcement training. Learn how to engage your mice\'s natural instincts and teach them simple tricks.","permalink":"/docs/Mice/care-and-husbandry/playing-and-training"},{"id":"Rabbits/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Rabbit","description":"Rabbits are intelligent, curious animals that need daily mental and physical stimulation. Learn how to play with and train your rabbit using positive reinforcement.","permalink":"/docs/Rabbits/care-and-husbandry/playing-and-training"},{"id":"Rats/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Rat","description":"A guide to playing with and training your pet rats, offering ideas for enrichment, toys, and teaching simple tricks to engage their intelligence.","permalink":"/docs/Rats/care-and-husbandry/playing-and-training"},{"id":"general-care/daily-care/socializing-your-small-pet","title":"Socializing Your Small Pet","description":"A guide to socializing and building trust with timid small pets like rabbits, guinea pigs, and rodents, using patience and positive reinforcement to create a strong bond.","permalink":"/docs/general-care/daily-care/socializing-your-small-pet"},{"id":"Chinchillas/health/understanding-chinchilla-behavior","title":"Understanding Chinchilla Behavior: A Guide for Owners","description":"Chinchillas are active, curious animals with a surprisingly rich behavioral repertoire. They are crepuscular \u2014 most active at dawn and dusk \u2014 and can live for 15 years or more.","permalink":"/docs/Chinchillas/health/understanding-chinchilla-behavior"},{"id":"Degus/health-and-wellness/understanding-degu-behavior","title":"Understanding Degu Behavior: A Guide for Owners","description":"Degus are highly social, intelligent, and vocal rodents from Chile, often described as having the curiosity of a rat and the social complexity of a prairie dog...","permalink":"/docs/Degus/health-and-wellness/understanding-degu-behavior"},{"id":"Ferrets/health-and-wellness/understanding-ferret-behavior","title":"Understanding Ferret Behavior: A Guide for Owners","description":"Ferrets are playful, mischievous, and highly social animals with a personality that is often described as a cross between a cat and a dog. Understanding their unique behaviors is key to a happy, healthy ferret.","permalink":"/docs/Ferrets/health-and-wellness/understanding-ferret-behavior"},{"id":"Gerbils/health-and-wellness/understanding-gerbil-behavior","title":"Understanding Gerbil Behavior: A Guide for Owners","description":"Gerbils are highly social, curious animals that communicate through a combination of body language, scent marking, and vocalizations.","permalink":"/docs/Gerbils/health-and-wellness/understanding-gerbil-behavior"},{"id":"guinea-pigs/health-and-wellness/understanding-guinea-pig-behavior","title":"Understanding Guinea Pig Behavior: A Guide for Owners","description":"Guinea pigs are highly vocal, social animals with a rich repertoire of sounds and body language. Learning to read their cues is one of the most rewarding parts of guinea pig ownership.","permalink":"/docs/guinea-pigs/health-and-wellness/understanding-guinea-pig-behavior"},{"id":"Hamsters/health-and-wellness/understanding-hamster-behavior","title":"Understanding Hamster Behavior: A Guide for Owners","description":"Hamsters are solitary, nocturnal animals with a fascinating range of behaviors. Learning to read their body language is essential for building trust and keeping them healthy.","permalink":"/docs/Hamsters/health-and-wellness/understanding-hamster-behavior"},{"id":"Hedgehogs/health-and-wellness/understanding-hedgehog-behavior","title":"Understanding Hedgehog Behavior: A Guide for Owners","description":"Hedgehogs are unique and fascinating creatures with a set of behaviors all their own. As solitary and nocturnal animals, their communication is often quiet and defensive...","permalink":"/docs/Hedgehogs/health-and-wellness/understanding-hedgehog-behavior"},{"id":"Mice/health-and-wellness/understanding-mouse-behavior","title":"Understanding Mouse Behavior: A Guide for Owners","description":"Mice are intelligent, curious, and surprisingly complex little animals. While often quiet, they have a rich system of communication based on body language, scent, and ultrasonic sounds...","permalink":"/docs/Mice/health-and-wellness/understanding-mouse-behavior"},{"id":"Rabbits/health-and-wellness/understanding-rabbit-behavior","title":"Understanding Rabbit Behavior: A Guide for Owners","description":"Rabbits are highly expressive animals whose body language is subtle but rich. Understanding what your rabbit is communicating is key to building a trusting relationship and catching health problems early.","permalink":"/docs/Rabbits/health-and-wellness/understanding-rabbit-behavior"},{"id":"Rats/health-and-wellness/understanding-rat-behavior","title":"Understanding Rat Behavior: A Guide for Owners","description":"Rats are intelligent, social, and emotionally complex animals. Understanding their natural behaviors and unique ways of communicating is key to building a strong bond and providing them with the best...","permalink":"/docs/Rats/health-and-wellness/understanding-rat-behavior"}],"unlisted":false}}')}}]);